from pathlib import Path
import re,json,html
ROOT=Path(__file__).resolve().parent
src=(ROOT/'논문31편_실험비교.md').read_text(encoding='utf8')
items=[]
for m in re.finditer(r'^## (D\d\d) · (.*?) · (.*?)\n(.*?)(?=^## |\Z)',src,re.M|re.S):
 d={'id':m[1],'title':m[2],'year':m[3]}
 for k,v in re.findall(r'^- \*\*(.*?)\*\*: (.*)$',m[4],re.M):d[k]=v
 items.append(d)
assert len(items)==31
notes=src.split('## 확인 범위와 연도 출처')[1]
notes=html.escape(notes)
notes=re.sub(r'https://[^\s<]+',lambda m:f'<a href="{m[0]}" target="_blank" rel="noopener">{m[0]}</a>',notes)
